/// Both ISINs must share the first 9 characters and carry the equity code `01`.
fn same_equity_issuer(raw: &str, current: &str) -> bool {
    raw.len() == 12
        && current.len() == 12
        && raw.is_ascii()
        && current.is_ascii()
        && raw.starts_with("IN")
        && raw != current
        && raw[..9] == current[..9]
        && &raw[7..9] == "01"
}

