//! A single official rename is metadata, never financial approval. Raw imports
//! remain immutable; a separate, revalidated proof names the adjustment owner.
use super::*;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

pub(super) const DECISION: &str = "VERIFIED_SPLIT_BONUS_SYMBOL_CHAIN_R1";
const VERSION: &str = "SPLIT_BONUS_SYMBOL_CHAIN_R1";

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub(in crate::database) struct Proof {
    pub(in crate::database) target: String,
    identity: Value,
    scan: Value,
    event: Value,
    database: String,
    previous_date: String,
    previous_close: f64,
}

fn digest(bytes: &[u8]) -> String { format!("{:x}", Sha256::digest(bytes)) }

fn has_table(c: &Connection, table: &str) -> AppResult<bool> {
    c.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name=?)",
        [table], |r| r.get(0)).map_err(|e| e.to_string())
}

/// No scan or stored decision is trusted here. Only exact official identity and
/// event evidence may select an alias; it must still pass financial validation.
fn identity(c: &Connection, row: &CorporateActionImportRow) -> AppResult<Option<(String, Value)>> {
    if row.exchange != "NSE" || row.source != "NSE_API" || row.parse_status != "PARSED"
        || !matches!(row.action_type.as_str(), "SPLIT" | "BONUS")
        || !matches!(row.review_status.as_str(), "UNRESOLVED" | "PENDING_ISIN_MISMATCH" | "PENDING")
        || row.approved_corporate_action_id.is_some()
        || split_bonus_terms::blocker(&row.purpose_raw).is_some()
        || !has_table(c, "corporate_action_symbol_chain_sources")? {
        return Ok(None);
    }
    let (Some(raw), Some(isin), Some(date)) = (&row.symbol, &row.isin, &row.ex_date) else { return Ok(None); };
    if NaiveDate::parse_from_str(date, "%Y-%m-%d").is_err() { return Ok(None); }
    let source = c.query_row("SELECT id,source_url,source_hash,raw_csv,captured_at,
        captured_at>=datetime('now','-1 day') AND captured_at<=datetime('now','+5 minutes')
        FROM corporate_action_symbol_chain_sources ORDER BY id DESC LIMIT 1", [], |r| Ok((
            r.get::<_,i64>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?,
            r.get::<_,Vec<u8>>(3)?,r.get::<_,String>(4)?,r.get::<_,bool>(5)?)))
        .optional().map_err(|e|e.to_string())?;
    let Some((source_id,url,hash,bytes,captured,fresh)) = source else { return Ok(None); };
    let parsed = reqwest::Url::parse(&url).ok();
    if !fresh || bytes.len()>2_000_000 || digest(&bytes)!=hash
        || super::super::official_source_urls::validate_nse_official_source_url(&url).is_err()
        || !parsed.is_some_and(|u|u.scheme()=="https" && u.path()=="/content/equities/symbolchange.csv")
        || super::super::official_source_urls::load_official_source_urls(Some(c))?.nse_symbol_change_url != url {
        return Ok(None);
    }
    let Ok(edges) = super::super::nse_identity_imports::parse_ca_symbol_change_source(&bytes) else { return Ok(None); };
    let outgoing: Vec<_> = edges.iter().filter(|e|e.0==*raw).collect();
    if outgoing.len()!=1 { return Ok(None); }
    let edge = outgoing[0];
    let target = &edge.1;
    if target==raw || date>=&edge.2 || edges.iter().filter(|e|
        e.0==*raw || e.1==*raw || e.0==*target || e.1==*target).count()!=1 {
        return Ok(None);
    }
    let mut stmt=c.prepare("SELECT id,current_symbol,old_symbol,new_symbol,effective_date,source
        FROM instrument_identity_history WHERE exchange='NSE' AND change_type IN ('SYMBOL_CHANGE','BOTH')
        AND (old_symbol IN (?,?) OR new_symbol IN (?,?) OR current_symbol IN (?,?))").map_err(|e|e.to_string())?;
    let history=stmt.query_map(params![raw,target,raw,target,raw,target],|r|Ok((r.get::<_,i64>(0)?,
        r.get::<_,Option<String>>(1)?,r.get::<_,Option<String>>(2)?,r.get::<_,Option<String>>(3)?,
        r.get::<_,String>(4)?,r.get::<_,Option<String>>(5)?)))
        .map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;
    if history.len()!=1 { return Ok(None); }
    let h=&history[0];
    if h.1.as_deref()!=Some(target) || h.2.as_deref()!=Some(raw) || h.3.as_deref()!=Some(target)
        || h.4!=edge.2 || h.5.as_deref()!=Some("NSE_IDENTITY") { return Ok(None); }
    let mut members=Vec::new();
    for (symbol,active) in [(raw,0_i64),(target,1_i64)] {
        let mut stmt=c.prepare("SELECT isin,is_active FROM instruments WHERE exchange='NSE' AND symbol=?").map_err(|e|e.to_string())?;
        let values=stmt.query_map([symbol],|r|Ok((r.get::<_,Option<String>>(0)?,r.get::<_,Option<i64>>(1)?)))
            .map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;
        if values.len()!=1 || values[0].1!=Some(active) { return Ok(None); }
        members.push(values[0].clone());
    }
    let Some(current)=members[1].0.as_deref() else { return Ok(None); };
    if members[0].0.as_deref()!=Some(current) || isin.len()!=12 || !isin.is_ascii()
        || !isin.starts_with("IN") || &isin[7..9]!="01" {
        return Ok(None);
    }
    if isin!=current && (!split_isin_price_proof::same_equity_issuer(isin,current)
        || !split_isin_price_proof::event_includes_equity_split(row)) { return Ok(None); }
    let unrelated:bool=c.query_row("SELECT EXISTS(SELECT 1 FROM (
        SELECT symbol,exchange FROM instruments WHERE isin IN (?,?)
        UNION SELECT symbol,exchange FROM instrument_isin_history WHERE isin IN (?,?))
        WHERE exchange<>'NSE' OR symbol NOT IN (?,?))",params![isin,current,isin,current,raw,target],|r|r.get(0)).map_err(|e|e.to_string())?;
    if unrelated { return Ok(None); }
    let Some(witness)=dated_symbol_chain::price_witness(c,row,raw)? else { return Ok(None); };
    let Some(context)=super::super::eod_data::resolve_instrument_context(c,target,"NSE")? else { return Ok(None); };
    if context.current_symbol!=*target || context.isin.as_deref()!=Some(current)
        || context.related_symbols.iter().any(|s|s!=raw && s!=target)
        || context.symbol_transitions.len()!=1
        || context.symbol_transitions[0].old_symbol.as_deref()!=Some(raw)
        || context.symbol_transitions[0].new_symbol.as_deref()!=Some(target)
        || context.symbol_transitions[0].effective_date!=edge.2 { return Ok(None); }
    Ok(Some((target.clone(),serde_json::json!({"version":VERSION,"source":[source_id,url,hash,captured],
        "edge":edge,"history":h,"members":members,"witness":witness}))))
}

/// Event precedes the sole rename, so both bars must belong to the old alias.
/// Never substitute a current-alias file or SQL underneath an existing binary.
pub(super) fn trade_window(c:&Connection,folder:&Path,row:&CorporateActionImportRow)
    ->AppResult<Option<(ScannedBar,ScannedBar)>> {
    let Some((_,meta))=identity(c,row)? else { return Ok(None); };
    let raw=row.symbol.as_deref().unwrap(); let date=row.ex_date.as_deref().unwrap();
    let window=if folder.join("eod_data").join("NSE").join(format!("{raw}.eod")).exists() {
        load_binary_trade_window(folder,raw,"NSE",date)?
    } else if get_price_storage_mode(c)==PriceStorageMode::Hybrid {
        load_sqlite_trade_window(c,raw,"NSE",date)?
    } else { None };
    let Some((previous,ex))=window else { return Ok(None); };
    let rename=meta["edge"][2].as_str().unwrap_or("");
    let today=chrono::Utc::now().with_timezone(&chrono::FixedOffset::east_opt(19800).unwrap()).date_naive();
    if ensure_import_trade_window_ready(Some(&(previous.clone(),ex.clone())),date,today).is_err()
        || previous.date.as_str()>=rename || ex.date.as_str()>=rename { return Ok(None); }
    Ok(Some((previous,ex)))
}

fn evaluate(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<Option<Proof>> {
    let Some((target,identity))=identity(c,row)? else { return Ok(None); };
    if ensure_split_bonus_price_validation(c,row,false).is_err() { return Ok(None); }
    let Some(scan)=load_latest_official_split_bonus_validation(c,row.id)? else { return Ok(None); };
    if scan.symbol!=row.symbol || scan.exchange!=row.exchange { return Ok(None); }
    let Some((previous,ex))=trade_window(c,folder,row)? else { return Ok(None); };
    if scan.prev_trade_date.as_deref()!=Some(&previous.date) || scan.ex_trade_date.as_deref()!=Some(&ex.date)
        || scan.prev_close.map(f64::to_bits)!=Some(previous.close.to_bits())
        || scan.ex_open.map(f64::to_bits)!=Some(ex.open.to_bits())
        || scan.ex_close.map(f64::to_bits)!=Some(ex.close.to_bits()) { return Ok(None); }
    let database:String=c.query_row("SELECT file FROM pragma_database_list WHERE name='main'",[],|r|r.get(0)).map_err(|e|e.to_string())?;
    Ok(Some(Proof {target,identity,scan:serde_json::to_value(scan).map_err(|e|e.to_string())?,
        event:serde_json::json!({"id":row.id,"symbol":row.symbol,"isin":row.isin,"source":row.source,
            "sourceFile":row.source_file,"purpose":row.purpose_raw,"date":row.ex_date,"recordDate":row.record_date,
            "action":row.action_type,"factor":row.factor,"priceFactor":row.price_factor,"ratio":[row.ratio_num,row.ratio_den],
            "face":[row.old_face_value,row.new_face_value],"cash":row.cash_amount}),
        database:database.replace('/',"\\"),previous_date:previous.date,previous_close:previous.close}))
}

impl Proof {
    pub(in crate::database) fn fingerprint(&self)->AppResult<String> {
        Ok(digest(&serde_json::to_vec(self).map_err(|e|e.to_string())?))
    }
    pub(in crate::database) fn previous(&self)->(&str,f64) {(&self.previous_date,self.previous_close)}
}

pub(in crate::database) fn verified(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<Option<Proof>> {
    if !has_table(c,"corporate_action_split_bonus_chain_proofs")? {return Ok(None);}
    let stored=c.query_row("SELECT proof_json,fingerprint FROM corporate_action_split_bonus_chain_proofs WHERE import_id=?",
        [row.id],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).optional().map_err(|e|e.to_string())?;
    let Some((json,hash))=stored else {return Ok(None);};
    let Ok(proof)=serde_json::from_str::<Proof>(&json) else {return Ok(None);};
    let Some(current)=evaluate(c,folder,row)? else {return Ok(None);};
    Ok(if proof==current && current.fingerprint()?==hash {Some(current)} else {None})
}

pub(super) fn has_decision(c:&Connection,id:i64)->AppResult<bool> {
    c.query_row("SELECT EXISTS(SELECT 1 FROM corporate_action_import_decisions WHERE import_id=? AND decision_type=?)",
        params![id,DECISION],|r|r.get(0)).map_err(|e|e.to_string())
}

pub(super) fn prepare(c:&Connection,folder:&Path,row:&CorporateActionImportRow)->AppResult<()> {
    let Some(proof)=evaluate(c,folder,row)? else {
        if has_decision(c,row.id)? {identity_recheck::recheck_pending_machine_identity(c,row)?;}
